document.addEventListener("DOMContentLoaded", () => {
  const state = {
    altitude: 0,
    integrity: 100,
    active: false,
    logs: [],
    simulationInterval: null
  };

  const stage = document.getElementById("app-stage");
  const logContainer = document.getElementById("live-log");

  function updateUI() {
    if (!stage) return;
    stage.innerHTML = `
      <div style="text-align: center; padding: 20px;">
        <h2 style="color: #00ffcc; text-shadow: 0 0 10px rgba(0,255,204,0.5);">الارتفاع الحالي: ${state.altitude}m</h2>
        <div style="width: 100%; background: #222; height: 10px; border-radius: 5px; margin: 10px 0;">
          <div style="width: ${state.integrity}%; background: ${state.integrity > 30 ? '#00ffcc' : '#ff3366'}; height: 100%; transition: width 0.3s;"></div>
        </div>
        <p>سلامة الهيكل: ${state.integrity}%</p>
        <div style="font-size: 0.8rem; color: #888;">الحالة: ${state.active ? 'قيد الصعود...' : 'جاهز للإنطلاق'}</div>
      </div>
    `;
  }

  function addLog(message) {
    const entry = document.createElement("div");
    entry.style.padding = "5px 0";
    entry.style.borderBottom = "1px solid #333";
    entry.innerHTML = `<span style="color: #00ffcc;">[${new Date().toLocaleTimeString()}]</span> ${message}`;
    logContainer.prepend(entry);
    state.logs.push({ time: new Date().toISOString(), message });
  }

  window.runPrimaryAction = () => {
    if (state.active) return;
    state.active = true;
    addLog("بدء عملية الصعود العمودي (The Vertical Climb)...");

    state.simulationInterval = setInterval(() => {
      if (state.integrity <= 0) {
        window.resetSimulation();
        addLog("فشل حرج: تم إنهاء المحاكاة بسبب تدهور سلامة الهيكل.");
        return;
      }

      state.altitude += Math.floor(Math.random() * 50) + 10;
      state.integrity -= Math.floor(Math.random() * 3);

      if (state.altitude % 100 < 20) {
        addLog(`تجاوز علامة الـ ${state.altitude} متر بنجاح.`);
      }

      updateUI();
    }, 500);
  };

  window.resetSimulation = () => {
    clearInterval(state.simulationInterval);
    state.active = false;
    state.altitude = 0;
    state.integrity = 100;
    state.logs = [];
    logContainer.innerHTML = "";
    addLog("تمت إعادة ضبط محرك نيكسوس السيادي.");
    updateUI();
  };

  window.exportDataSnapshot = () => {
    const data = JSON.stringify(state, null, 2);
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    addLog("تم توليد لقطة بيانات فورية للمحاكاة.");
    console.log("Exported State Snapshot:", state);
    alert("تم تصدير سجلات الحالة إلى الكونسول وبصيغة افتراضية.");
  };

  // Initial Render
  updateUI();
  addLog("تم تهيئة نظام 'نيكسوس' - بانتظار أوامر التشغيل.");
});
